from __future__ import annotations

import json
import subprocess
from pathlib import Path

from .scanners import CheckResult


def _gh_json(args: list[str], cwd: Path) -> object | None:
    try:
        p = subprocess.run(
            ["gh", *args],
            cwd=str(cwd),
            capture_output=True,
            text=True,
            check=False,
            timeout=60,
        )
    except (FileNotFoundError, subprocess.TimeoutExpired):
        return None
    if p.returncode != 0:
        return None
    try:
        return json.loads(p.stdout)
    except json.JSONDecodeError:
        return None


def gap_issue_payload(r: CheckResult) -> tuple[str, str, str]:
    """Return (marker, title, body) for a failing scanner result."""
    marker = f"scanner_id:{r.scanner_id}"
    body = (
        f"## House scan gap\n\n"
        f"`{marker}`\n\n"
        f"| Field | Value |\n|-------|-------|\n"
        f"| Scanner | {r.name} (`{r.scanner_id}`) |\n"
        f"| Status | `{r.status}` |\n"
        f"| Raw compliance % | {r.compliance_pct}% |\n"
        f"| Message | {r.message} |\n"
        f"| Waiver path | `{r.waiver_path or 'security/waivers/' + r.scanner_id + '.yaml'}` |\n\n"
        f"**Action:** fix findings **or** complete a **per-scanner** waiver at "
        f"`security/waivers/{r.scanner_id}.yaml` (reason ≥20, owner, ticket, expires_on).\n\n"
        f"_Generated by house_scan. Do not put secrets in this issue._\n"
    )
    title = f"[house-scan] Gap: {r.scanner_id} ({r.compliance_pct}%)"
    return marker, title, body


def plan_gap_issues(
    results: list[CheckResult],
    existing: list[dict] | None = None,
) -> list[dict]:
    """Plan create/update actions for failing results (pure; no network).

    Each plan item: {action: create|update, scanner_id, marker, title, body, number?}
    Used by open_gap_issues and dry-run dogfood (library#13).
    """
    existing = existing or []
    plans: list[dict] = []
    for r in results:
        if r.status not in ("fail", "error"):
            continue
        marker, title, body = gap_issue_payload(r)
        found_num = None
        for issue in existing:
            if not isinstance(issue, dict):
                continue
            if marker in (issue.get("body") or ""):
                found_num = issue.get("number")
                break
        if found_num is not None:
            plans.append(
                {
                    "action": "update",
                    "scanner_id": r.scanner_id,
                    "marker": marker,
                    "title": title,
                    "body": body,
                    "number": found_num,
                }
            )
        else:
            plans.append(
                {
                    "action": "create",
                    "scanner_id": r.scanner_id,
                    "marker": marker,
                    "title": title,
                    "body": body,
                    "number": None,
                }
            )
    return plans


def open_gap_issues(
    repo: Path,
    results: list[CheckResult],
    *,
    dry_run: bool = False,
) -> list[str]:
    """Create or update issues for failing non-waived scanners. Returns messages.

    dry_run=True: plan only (no gh create/comment); still may list open issues
    when gh is available so dedupe can be demonstrated.
    """
    messages: list[str] = []
    if dry_run:
        messages.append("DRY_RUN: no issues will be created or commented")

    if not dry_run:
        # Ensure labels
        subprocess.run(
            [
                "gh",
                "label",
                "create",
                "house-scan-gap",
                "--color",
                "B60205",
                "--description",
                "House scanner compliance gap",
            ],
            cwd=str(repo),
            capture_output=True,
            check=False,
        )
        subprocess.run(
            [
                "gh",
                "label",
                "create",
                "security-tooling",
                "--color",
                "0E8A16",
                "--description",
                "Security tooling",
            ],
            cwd=str(repo),
            capture_output=True,
            check=False,
        )

    existing_raw = _gh_json(
        [
            "issue",
            "list",
            "--label",
            "house-scan-gap",
            "--state",
            "open",
            "--json",
            "number,body,title",
            "--limit",
            "50",
        ],
        repo,
    )
    existing: list[dict] = existing_raw if isinstance(existing_raw, list) else []
    if existing_raw is None and not dry_run:
        messages.append("WARN: gh not available or not authenticated; skip --open-issues")
        return messages
    if existing_raw is None and dry_run:
        messages.append("DRY_RUN: gh unavailable — planning as if no existing gap issues")
        existing = []

    plans = plan_gap_issues(results, existing)
    if not plans:
        messages.append("No failing scanners; nothing to open")
        return messages

    # Simulate dedupe in dry-run after first create in-memory
    seen_markers: dict[str, int] = {}
    for issue in existing:
        if isinstance(issue, dict) and issue.get("body"):
            for p in plans:
                if p["marker"] in (issue.get("body") or ""):
                    seen_markers[p["marker"]] = int(issue.get("number") or 0)

    for p in plans:
        if dry_run:
            # Second call simulation: if we already "created" this marker, treat as update
            if p["marker"] in seen_markers and p["action"] == "create":
                p = {**p, "action": "update", "number": seen_markers[p["marker"]]}
            if p["action"] == "update":
                messages.append(
                    f"DRY_RUN would update issue #{p.get('number')} for {p['scanner_id']}"
                )
            else:
                fake_num = 9000 + len(seen_markers)
                seen_markers[p["marker"]] = fake_num
                messages.append(
                    f"DRY_RUN would open issue for {p['scanner_id']} title={p['title']!r}"
                )
            continue

        if p["action"] == "update":
            subprocess.run(
                ["gh", "issue", "comment", str(p["number"]), "--body", p["body"]],
                cwd=str(repo),
                capture_output=True,
                check=False,
            )
            messages.append(f"Updated issue #{p['number']} for {p['scanner_id']}")
        else:
            proc = subprocess.run(
                [
                    "gh",
                    "issue",
                    "create",
                    "--title",
                    p["title"],
                    "--body",
                    p["body"],
                    "--label",
                    "house-scan-gap",
                    "--label",
                    "security-tooling",
                ],
                cwd=str(repo),
                capture_output=True,
                text=True,
                check=False,
            )
            if proc.returncode == 0:
                messages.append(f"Opened {proc.stdout.strip()} for {p['scanner_id']}")
            else:
                messages.append(
                    f"WARN: failed to open issue for {p['scanner_id']}: {proc.stderr}"
                )
    return messages
